#!/usr/bin/env node
// scripts/verify-build-facts.mjs
//
// Verifies build-order content against PRIMARY-SOURCE facts in
// src/data/game-facts.json (generated by build-game-facts.mjs from aalises data).
//
// Check: no build may reference a unit whose real Age is later than the build's
// targetAge (e.g. a Castle-Age Cavalry Archer in a Feudal build). This is the
// objective "unit produced before it exists" error class. Counter/strategy claims
// are NOT judged here (they need armour/speed context, not just data) — see docs/SOURCES.md.
//
// Exit 0 = clean; 1 = at least one age violation (so it can gate CI).

import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import yaml from "js-yaml";

const FACTS = path.resolve("src/data/game-facts.json");
const BUILDS = path.resolve("src/content/build-orders");

async function run() {
  const facts = JSON.parse(await readFile(FACTS, "utf8"));
  const { ageRank, units } = facts;

  const files = (await readdir(BUILDS)).filter((f) => f.endsWith(".yaml") || f.endsWith(".yml"));
  const violations = [];
  let checked = 0;

  for (const file of files) {
    const raw = await readFile(path.join(BUILDS, file), "utf8");
    const data = yaml.load(raw);
    const targetAge = data?.targetAge;
    if (!targetAge || !(targetAge in ageRank)) continue;
    checked++;
    const limit = ageRank[targetAge];
    const iconSlugs = new Set(
      (data?.steps ?? []).flatMap((s) => s.icons ?? []),
    );
    for (const slug of iconSlugs) {
      const unit = units[slug];
      if (!unit) continue;
      if (ageRank[unit.age] > limit) {
        violations.push(
          `${file}: "${slug}" is a ${unit.age}-age unit but the build targetAge is ${targetAge} ` +
            `(source: aalises units.csv).`,
        );
      }
    }
  }

  console.log(
    `Verified ${checked} build orders against game-facts.json (${Object.keys(units).length} sourced units).`,
  );
  if (violations.length) {
    console.error(`\n${violations.length} unit-age violation(s):`);
    for (const v of violations) console.error(`  - ${v}`);
    process.exit(1);
  }
  console.log("No unit-age violations. ✓");
}

run().catch((e) => {
  console.error(e.message);
  process.exit(1);
});
